rc=seq.translate(comp)[::-1]
STOP={'TAA','TAG','TGA'}
import re
def scan(s,tag):
    hits=[]
    # heptamer pattern XXXYYYZ: X run then Y run then Z; use regex for pattern A6G etc.
    for m in re.finditer(r'(?=([ACGT]{6}[ACGT]))',s):
        h=m.group(1)
        # require it to look like a shift site: triple repeat-ish
        if h[0]==h[1]==h[2] or h[3]==h[4]==h[5]:
            hits.append((m.start(),h))
    # filter to known-like: e.g. A AAA AAG  (positions p..p+6 where p%3==0)
    return hits
for tag,s in (('+',seq),('-',rc)):
    print('====',tag)
    for p,h in scan(s,tag):
        if p%3!=0: continue
        for d,newname in ((-1,'-1'),(1,'+1')):
            start = p+ (5 if d==-1 else 7)
            # compute ORF length till stop in the frame starting at start
            k=start
            n=0
            while k<len(s)-2 and s[k:k+3] not in STOP:
                n+=1; k+=3
            if n>=30:
                print(f"{tag} site@rc/p={p} hept={h} shift{d}: downstreamORF {n} aa (ends at {k})")
